#[cfg(feature = "validate")]
#[test]
fn rejects_invalid_examples() {
    use trust_tasks_rs::validate::ValidatedPayload;
    let fixtures: &[(&str, &str)] = &[
        (
            "No DID class. The VTA never infers one — from a template, a context or a path — because a DID belongs to one class for its life (VTI-KEY-193), and a guessed `service` would make a person's identifier a node's. Absent is refused, not defaulted.",
            "{\n  \"contextId\": \"alice\",\n  \"path\": \"people/alice\",\n  \"serverId\": \"prod\"\n}",
        ),
        (
            "An integration class. 0.1 spoke of integration DIDs; an integration's identity is a service DID (VTI-KEY-192), so the class is `service` and there is no fourth value.",
            "{\n  \"contextId\": \"bridge\",\n  \"didClass\": \"integration\",\n  \"serverId\": \"prod\"\n}",
        ),
        (
            "No hosting server. A did:webs DID is hosted only — the VTA has no inbound surface to serve one from — so there is no serverless form, and a request without `serverId` must fail validation rather than fall back to one.",
            "{\n  \"contextId\": \"alice\",\n  \"didClass\": \"persona\",\n  \"path\": \"people/alice\"\n}",
        ),
        (
            "The path carries the AID. The caller cannot know the AID — it is the digest of an inception event the VTA has not yet written — and the slot grammar is lowercase, so a case-sensitive AID segment is refused rather than taken as a path the VTA then appends a second AID to.",
            "{\n  \"contextId\": \"alice\",\n  \"didClass\": \"persona\",\n  \"path\": \"people/ENro7uf0ePmiK3jdTo2YCdXLqW7z7xoP6qhhBou6gBLe\",\n  \"serverId\": \"prod\"\n}",
        ),
        (
            "Caller-supplied key material. The VTA derives every key, with or without a template; a request naming a signing key is a request to custody a key the caller chose, and the closed schema refuses it.",
            "{\n  \"contextId\": \"alice\",\n  \"didClass\": \"persona\",\n  \"serverId\": \"prod\",\n  \"signingKeyId\": \"my-key\"\n}",
        ),
        (
            "A template and explicit services together. Two sources for one document would leave the operator unable to tell which shaped it, so they are exclusive rather than merged (CONVENTIONS.md §9.3).",
            "{\n  \"addTspService\": true,\n  \"contextId\": \"witness-1\",\n  \"didClass\": \"service\",\n  \"serverId\": \"prod\",\n  \"template\": \"dtg-witness\",\n  \"templateVars\": {\n    \"MEDIATOR_DID\": \"did:webvh:QmMediatorScid:mediator.example\"\n  }\n}",
        ),
        (
            "A template and explicit aliases together. The template's `alsoKnownAs` is the alias list; an explicit one beside it is a second source.",
            "{\n  \"alsoKnownAs\": [\n    \"did:webvh:QmWitnessScid:example.com:w1\"\n  ],\n  \"contextId\": \"witness-1\",\n  \"didClass\": \"service\",\n  \"serverId\": \"prod\",\n  \"template\": \"dtg-witness\"\n}",
        ),
        (
            "Template variables without a template. Nothing would render them, so a request carrying them has asked for something the VTA cannot do.",
            "{\n  \"contextId\": \"witness-1\",\n  \"didClass\": \"service\",\n  \"serverId\": \"prod\",\n  \"templateVars\": {\n    \"MEDIATOR_DID\": \"did:webvh:QmMediatorScid:mediator.example\"\n  }\n}",
        ),
        (
            "A template scope without a template.",
            "{\n  \"contextId\": \"witness-1\",\n  \"didClass\": \"service\",\n  \"serverId\": \"prod\",\n  \"templateContext\": \"witness-1\"\n}",
        ),
        (
            "A template name outside the template grammar. Names are lowercase letters, digits and hyphens; anything else names no template in any scope.",
            "{\n  \"contextId\": \"witness-1\",\n  \"didClass\": \"service\",\n  \"serverId\": \"prod\",\n  \"template\": \"DTG Witness\"\n}",
        ),
        (
            "A service id that is not a fragment. Ids are relative to the DID; an absolute id could name another DID's service.",
            "{\n  \"additionalServices\": [\n    {\n      \"id\": \"did:webs:other.example:EAbc#files\",\n      \"serviceEndpoint\": \"https://files.example.com\",\n      \"type\": \"FileStore\"\n    }\n  ],\n  \"contextId\": \"alice\",\n  \"didClass\": \"persona\",\n  \"serverId\": \"prod\"\n}",
        ),
    ];
    for (i, (note, raw)) in fixtures.iter().enumerate() {
        let value: serde_json::Value = match serde_json::from_str(raw) {
            Ok(v) => v,
            Err(_) => continue,
        };
        let serde_ok = serde_json::from_value::<spec::Payload>(value.clone()).is_ok();
        let schema_ok = spec::Payload::validate_value(&value).is_ok();
        assert!(
            !(serde_ok && schema_ok),
            "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
            i + 1,
            note,
            raw
        );
    }
}
